create function f_commit() returns void language plpgsql as $$
begin
  insert into respuestas (anonimo, pregunta, nivel, acierto, cliente_id) values (gen_random_uuid(), 'x', 1, true, gen_random_uuid());
  commit;
end $$;
select f_commit();

