// El teléfono (src/datos/puntaje.ts): coma flotante binaria
const telefono = (ms) => Math.round(1000 * (1 - (ms / 20000) / 2));

// La base: decimales exactos. Se simula con enteros: 1000 - ms/40 = (40000 - ms) / 40,
// y la mitad exacta sube (round de numeric empata alejándose de cero)
const base = (ms) => Math.floor((2 * (40000 - ms) + 40) / 80);

let difieren = 0, primero = null;
for (let ms = 300; ms <= 20000; ms++) {
  if (telefono(ms) !== base(ms)) { difieren++; if (primero === null) primero = ms; }
}
console.log("tiempos probados:", 20000 - 300 + 1);
console.log("difieren:", difieren, "(el primero en ms =", primero + ")");
console.log("1000*(1-(5140/20000)/2) en JavaScript =", 1000 * (1 - (5140 / 20000) / 2));
console.log("teléfono:", telefono(5140), "| base:", base(5140));

